/** Writes spec/platform-api.yaml from the use cases. `--check` fails if the checked-in file is out of date (CI). */
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { stringify } from "yaml";
import { buildOpenApi } from "../src/openapi";

const file = join(import.meta.dirname, "../../spec/platform-api.yaml");
const text =
  "# Generated by platform/scripts/gen-openapi.ts from the use cases – do not edit. Run: cd platform && npm run openapi\n" +
  stringify(buildOpenApi(), { lineWidth: 0 });

if (process.argv.includes("--check")) {
  let current = "";
  try {
    current = readFileSync(file, "utf8").replace(/\r\n/g, "\n");
  } catch {}
  if (current !== text) {
    console.error("spec/platform-api.yaml is out of date. Run: cd platform && npm run openapi");
    process.exit(1);
  }
  console.log("spec/platform-api.yaml is up to date");
} else {
  writeFileSync(file, text);
  console.log(`wrote ${file}`);
}
